      "sourceNote": "來源包含《2010年12月日语能力测试N3真题+答案.pdf》（重新排版PDF，19頁，文字層乾淨可選取，前15頁題目、後4頁為掃描表格式「参考答案」）、《2010年12月N3听解原文.pdf》（沪江日语绿宝书，聴解逐字稿+部分参考答案）、《2010年12月日语能力考试N3真题解析).doc》（新世界日语名师解析，逐題中文解析+正解，antiword轉出）、10.12参考答案資料夾內4張JPG掃描答案表（听力/文字词汇/语法/读解，新世界日语）、以及《2010年12月.mp3》聴解全程音檔（41分30秒）。\n\n【重大發現：真题PDF的文字語彙／文法／読解部分，經交叉驗證判斷極可能不是2010年12月N3這場考試的真實內容，本次JSON僅收錄可信驗證過的聴解部分，文字語彙／文法／読解部分予以排除，詳細理由如下】\n驗證方式與具體矛盾證據：\n(1) 聴解部分【已用實際音檔直接證偽】：用openai-whisper對listening.mp3開頭4分鐘實際做語音轉文字，轉出內容（大学のゼミのスキー旅行為題材、女學生確認人數）與《2010年12月N3听解原文.pdf》（沪江）逐字稿完全吻合，音檔開場白也清楚報出「2010年第2回日本語能力試験N3」（確認為2010年第2次即12月場次、新制N3無誤）；但真题PDF自己印刷的聴解問題1選項文字（「水の量を増やす／減らす、ひりょうを増やす／減らす」「ごみ袋を買う」等）與此音檔內容完全不相關、對不上。這是唯一能用音檔直接證實的部分，結論明確：真题PDF的聴解頁面與本場考試的真實音檔不是同一份試卷。\n(2) 文字語彙部分【題數結構矛盾】：真题PDF文字語彙只有4個大題共25題（問題1:6題／問題2:7題／問題3:6題／問題4:6題），但《…真题解析).doc》與「文字词汇.jpg」参考答案均一致描述並列出「問題1〜5共35題（8+6+11+5+5）」，題型結構與2010年7月N3（同樣5大題）一致，doc/JPG彼此答案數字完全吻合，卻與真题PDF自己內嵌的（後4頁掃描）参考答案表對不上：例如第1題，真题PDF內嵌答案給1、doc/JPG給3，且對應的題目文字本身就完全不同（真题PDF第1題考「時間が経つにつれて、選手の動きが鈍ってきた」的畫線讀音，doc/JPG描述的第1題卻是考「空席」的讀音）。\n(3) 文法部分【題數結構矛盾】：真题PDF文法問題1（助詞篏空）只有10題（26〜35），但doc/JPG描述為13題（1〜13）。\n(4) 読解部分【題量矛盾】：真题PDF読解共25題（46〜70，橫跨6個大題，含2個獨立的「長文」大題），但doc明確寫道「題型和上次考試（7月）一樣，短文4篇、中文2篇、長文1篇、信息搜索1題」——這正是2010年7月N3読解僅16題的標準格式，真题PDF卻多了將近一倍的題量，對不上。\n以上4項證據互相印證（尤其(1)是可以直接用音檔驗證的鐵證），結論：真题PDF很可能是編纂過程中誤植/誤附了另一份文件（或是把兩份不同試卷的內容混在一起），並非2010年12月N3的真實考卷，至少聴解部分可以百分之百確定不是。由於doc解析僅提供正解單字/文法點＋簡短中文說明，並未印出完整原句與全部4個選項文字，不足以在不捏造內容的前提下重新組出可信的原始考題，因此本次「文字語彙／文法／読解」部分不予收錄轉錄，僅在此sourceNote與openDecisions完整記錄調查過程，留待未來取得可信的原始考卷後再補做。\n\n聴解部分改以audio-verified的沪江逐字稿＋新世界日语doc解析為準（両者答案與逐字稿內容一致）：問題3/4/5有完整選項文字可正常收錄為可作答item；問題1/2僅有對話逐字稿（已用whisper對照mp3驗證無誤），但正式考卷上應該印刷的4個選項文字（動作描述短句）在提供的所有來源中都找不到可信版本，因此這12題只保留script與問い，不附meaning，比照exam-parse-prompt.md「沒把握就不加meaning」的既有原則，不會進入可作答題庫。",
      "questionNumber": "lis-I-4",
