    "script": "女：木村さん、明日の午後三時ごろ、仕事入ってる。\n男：ええと、大丈夫ですけど。\n女：実はね、急に出張に行くことになって。\n男：そうですか。\n女：それで、明日の会議ちょっと出られそうにないから、悪いんだけど、かわりに出てくれる？\n男：わかりました。\n女：会議の時間と場所は後でメールで送るから。\n男：はい。\n女：それから、この前の会議の記録、今持ってくれない？分からないことがあったら、聞いて。\n男：はい。わかりました。\n女：出席者が変わることは私から電話しとくから。\n男：はい。",
    "reviewNote": "正解は選項3相当（この前の会議の記録を今見る）。原始選項文字は未收錄。"
