    "script": "男：来週、小学校に行くことになっていますね。小学校では、みんなさんの国を子供たちに紹介します。紹介する時に、国の写真を使いますから、忘れないで持ってきてください。食べ物の紹介をしたい人はいますか。食べ物は子供たちにあげられませんから、持ってこないでください。何か質問はありますか。ええ、では、今から名札を配りますので、当日必ず持ってきてください。",
