    "script": "男：来月、留学生のパーティーがあるよね。みんなの前で、歌か何かやってほしいって頼まれたんだけど……\n女：うん。\n男：僕、歌は自信がないんだけど、何かない？\n女：じゃあ、ダンスとか、どう？\n男：ダンスか……\n女：それから、この前のパーティーでは、バイオリンを弾いてた人がいたけど、あういうのもいいよね。\n男：うん。\n女：そういえば、ギターできたんじゃない？\n男：前はよく引いてたけど、もう一年以上やってないんだ。\n女：大丈夫、上手だったじゃない。\n男：じゃあ、久しぶりに練習して、やってみるよ。",
