    "script": "男：先週病院で、すこし運動するように言われちゃったんだ。\n女：そう……じゃあ、会社の近くのプールで泳いだらどう？\n男：おお、水の中で歩くだけでも運動になるんだってね、でも、着替えるのが面倒くさいんだよなぁ。\n女：もう、またそんなこと言って。じゃあ、ジョギングとかサイクリングとかは？どっちも簡単だし、すぐに始められるし。\n男：そうか、会社まで自転車できたらいいんだ、バスをやめて。\n女：そうよ、いい運動になるよ。\n男：じゃあ、明日から始めよう。",
    "reviewNote": "正解は選項4相当（自転車通勤）。原始選項文字は未收錄（理由は問題1共通のreviewNote参照）。"
