    "script": "女：ねえ、試合が近いから、今度の土曜日も、みんなで練習しようと思うんだけど、来られる？\n男：ん～実は、いま両親が国から来ていて、土曜日は……\n女：そうなんだ。どこか行くの？\n男：うん、ちょっと案内しようと思って。でも、日曜日だったら、両親を空港に見送りに行った後、三時には行けるよ。\n女：あれ、アルバイトじゃなかった？\n男：あっ、アルバイトは休みをもらっているから大丈夫。",
