    "script": "男：あれ、編み物？今度は何編んでるの？\n女：あっ、これ？セーター。\n男：この前も編んでたでしょう。\n女：うん、あれは、私のマフラーと帽子、これは、母にあげようと思って。\n男：へー。編み物って面白い？\n女：うん、難しいけどすごく面白いよ、どんどん編みたくなっちゃう。これができたら、次は、自分のセーターを編むつもり。\n男：へー、そうなんだ。\n女：木村さんも始めてみたら？教えてあげるよ。",
