    "script": "女：私、最近、猫を飼い始めたんだ。\n男：あれ、前は犬がほしいって言ってたのに、どうして？あっ、猫のほうが静かだから？\n女：ん～そうじゃなくて……\n男：ああ、猫は世話しなくてもいいからか。\n女：ううん、餌をやらなきゃいけないし、汚れたらシャンプーもしなきゃいけないし。\n男：へえ、そうなんだ。最近一人暮らしをはじめて、さびしいから僕も猫でも飼おうかと思ってたけど、ちょっと大変そうだね。\n女：まあね、私も友達にもらわなかったら飼わなかったんだけど。\n男：へえ～\n女：でもね、飼い始めたら、可愛くて……\n男：そうなんだ。",
    "reviewNote": "正解は選項4相当（友達にもらったから）。原始選項文字は未收錄。"
