    "script": "女：田中君、どうしたの。その手、包帯して。\n男：ああ、これ、先週の金曜日、学校の帰りに自転車に乗ってて転んじゃって。\n女：そう、右手だと、鉛筆も持てないし、食事するのも大変でしょう。\n男：いや、僕は左利きだから、それは問題ないんだけど、やっぱりいろいろ不便だよ。包帯が濡れたらいけないから、頭を洗うのに苦労するし。\n女：大変ね。しばらくは自転車にも乗れないね。\n男：うん。今日もバスできたんだけど。たまにはバスもいいね。",
    "reviewNote": "正解は選項3相当（包帯を濡らさないよう頭を洗うのが大変）。原始選項文字は未收錄。"
