    "script": "女：おはようございます。田中さん早いですね。\n男：ええ、毎日8時前には会社に来てるんです。朝は静かで、仕事に集中できますから。\n女：え～、あっ、確か最近会社の近くに引越したんですよね。\n男：ええ、でも、引っ越す前から早く来てたんです。満員電車に乗るのがいやで、今は電車は使ってないんですけどね。\n女：ああ。\n男：あさは電話もかかってこないから、いいですよ。\n女：そうですね。私もあしたから早く来てみよう。",
