    "optionExplanations": [
      "正解：「うん、一回だけだけどね」直接回答去過、並補充只去過一次，是對「有沒有去過京都」最自然的回應。",
      "「いや、行かないこともあるよ」語意不通順，並未正面回答是否去過京都。",
      "「へえ、行ったんだ」應該是提問者聽到對方回答「去過」之後的反應語，並非被問的人自己會說的話，方向錯誤。"
    ]
