    "script": "図書館で、男の学生と係りの人が話しています。図書館のパソコンコーナーで何をしてはいけませんか。\n男：すみません、パソコンを使いたいんですが。\n女：はい、どうぞ。\n男：あのう、インターネットは使えますか。\n女：ええ、利用できます。でも、メールはご遠慮ください。\n男：わかりました。後、プリンタは？\n女：あっ、プリンタはお使えになれますが、有料です。\n男：あっ、そうですか。それから、DVDは見られますか？\n女：はい、大丈夫ですよ。\n図書館のパソコンコーナーで何をしてはいけませんか。",
