    "script": "大学で、男の留学生が係りの人にホームステイについて聞いています。男の留学生はどうして、ホームステイに参加できませんか。\n男：すみません、このホームステイに申し込みをしたいんですが、締め切り、まだですよね。\n女：はい、まだ間に合いますよ。参加は初めてですか。\n男：いいえ、二回目です。二回目でも大丈夫ですか。\n女：はい、大丈夫です、えー、日本に来て、どのぐらいになりますか。\n男：十ヶ月を過ぎたところです。後、一ヶ月で帰国する予定です。\n女：そうですか。うーん、実は、このホームステイは来日してから半年以内の留学生しか申し込みができないことになっているんですよ。\n男：えっ、そんなんですか。\n男の留学生はどうして、ホームステイに参加できませんか。",
