    "script": "テレビで男の人が自分の仕事について話しています。男の人は何がうれしいと言っていますか。\nM：私は新しく町にできたスーパーの社員です。でも、店の中では、働いていません。毎日、車で、新鮮な肉や魚など、店の商品を遠くの村まで売りにいっています。一日に、五つぐらいの村に行きます。お客さんは多い日も、少ない日もありますが、私の車が来るのを楽しみに待っていてください。皆さんに喜んでもらえるのがやっぱり私には一番うれしいです。\n男の人は何がうれしいと言っていますか。",
