    "script": "女の留学生と男の学生が話しています。女の留学生はどうして来週の国際交流会に行けませんか。\n女：来週、姉が日本に来るんだ。\n男：そう、お姉さん何日ぐらいいるの。\n女：一週間。\n男：じゃあ、国際交流会に一緒に来たら。来週、外国人のための着物教室があるって聞いたよ。\n女：本当？いいね、いつ？\n男：水曜日の1時から。\n女：えっ、ちょうどその時間は、姉を迎えに空港に行ってるんだ。だから、その日は無理だなあ。\n男：そっか。残念だね。\n女：うーん。姉が来たら週末には一緒に京都に行くんだ。生花もやってみたいって言ってるし。忙しくなりそう。\n女の留学生はどうして来週の国際交流会に行けませんか。",
