    "script": "留学生が話しています。この留学生が日本に来た目的は何ですか。\n女：はじめまして、マリヤと申します。今は日本語学校で勉強しています。国の大学にいたとき、日本人の友だちと、よく日本の映画を見たり、日本料理の店に行ったりしていました。それで、和食に関心を持つようになりました。来年、専門学校で日本料理の勉強をするつもりです。そのために、日本に来たので、学校を入れるように頑張ります。将来は国へ帰って、レストランを開きたいと思っています。この留学生が日本に来た目的は何ですか。",
