    "script": "ラジオで男の人が話しています。\nM：最近いやな匂いを消すための製品がよく売られていますね。しかし、例えば、食べ物が腐っている匂い、何か燃えている匂い、こういう匂いがまったくなかったらどうなるでしょうか。体の匂いの変化でわかる病気もあるそうです。匂いが感じられないということは危険でもあるのです。いろいろな匂いを感じながら毎日の生活を楽しむ、これが自然で健康的な生活だと私は思います。",
