    "script": "病院の受付で、男の人が話しています。男の人は、このあとどうしますか。\n男：あの…、初めてなんですけど。\n女：ではまず、こちらの用紙にお名前、住所、けがの具合などをご記入ください。それから、あちらの3番の窓口に用紙と保険証を出して、お待ちください。お名前が呼ばれたら、窓口に行ってください。\n男：あ、その用紙なら、もう書きました。これだけでいいんでしょうか。\n女：あ、はい、結構です。後は診察の時詳しくお聞きしますから。\n男の人は、この後どうしますか。",
