    "script": "電話で、男の人とお母さんが話しています。男の子は、このあとどうしますか。\n子：もしもし、お母さん、僕だけど…。あのね、鍵を忘れちゃって、うちに入れないんだ…。\n母：えっ！お母さんはまだしばらく帰れないわよ。管理人さんにお願いして、鍵あけてもらって。\n子：管理人さんは4時までしかいないんじゃなかった？\n母：え？ああ、もう4時半ね。困ったわね。\n子：じゃあ、お父さんに電話してみる。\n母：でも、お父さんの会社から家まで2時間ぐらいかかるんだから、今、すぐ帰れたとしても、2時間は待たなきゃならないわよ。じゃあ、おばあちゃんのうちに行ってなさい。\n子：おばあちゃんのうち？うん、わかった。\n母：じゃあ、お母さんが電話しておくから、おばあちゃんが迎えに来るまで、そこにいなさい。\n男の子は、このあとどうしますか。",
