    "script": "男の人と女の人が話しています。女の人は、どうして事故に会いましたか。\n男：どうしたの、そのけがが？\n女：ちょっと、交通事故。……って言っても、相手は自転車だけど。\n男：だから、音楽を聞きながら歩いてたら危ないって言ったじゃないか。\n女：そう言われてからは、しないようにしてるよ。このけがは、私のせいじゃないもん。悪いのは向こう。携帯電話をかけてたんだもん。\n男：ああ、そうなのか。最近、危ない乗り方してる人、多いよね。ぼくもこの間、傘を差して走ってる自転車にぶつかりそうになったよ。\n女の人は、どうして事故に会いましたか。",
