    "script": "女子学生と男子学生が話しています。男子学生はどうしてレポートを書きますか。\n女：中村くん、試験も終わったし、みんなでカラオケに行こうって言ってるんだけど、一緒に行かない？\n男：ああ、ぼくはやめておくよ。レポート書かなきゃならないんだ。\n女：レポート？そんな宿題あったっけ？あ、先週のレポート、まだ出してないの？\n男：いや、先生が言ってたじゃない。単位がもらえるかどうか心配な人は、もう一つレポート、出せって。\n女：ああ、あれね。中村くん、試験、できなかったの？\n男：いや、まあまあできてたとは思うんだけど、ぼく、出席がさ…。\n女：そういえば、よく休んでたよね。そっか、じゃあ、みんなには中村くんは行かないって伝えておくね。\n男子学生は、どうしてレポートを書きますか。",
