    "script": "女の人と男の人が話しています。女の人は読み終わった本をどうしていますか。\n女：ねえ、読み終わった本ってどうしてる？\n男：本？ぼくは古本屋に売っているよ。\n女：ああ、そう。本って、どんどんたまっちゃうけど、捨てられないのよね〜。私は図書館に持っていってるんだ。うちの近くの図書館は、読み終わっていらなくなった本を置いておく場所があるんだよ。\n男：へえ、図書館に持っていくと、お金もらえるの？\n女：もらえないよ。でも、好きな本はたくさんの人に読んでもらいたいじゃない。ああっ、古本屋って、お金のためなの？でも、あんまり、高くは売れないでしょ？\n男：うん。でも、ちょっとでも、もらえるほうがいいからね。\n女の人は、読み終わった本をどうしていますか。",
