    "script": "会社で、男の人と女の人が話しています。女の人は、どうして早く家に帰りたいのですか。\n男：仕事、終わったんでしょう？これからみんなと飲みに行くんだけど、倉田さんも一緒にどう？\n女：あ、今日はちょっと…。\n男：何か予定でもあるの？\n女：いえ、予定というか、早く家に帰らないと…。\n男：まだ6時だよ。少しぐらい、いいでしょう？行こうよ。\n女：ええ、行きたいんですけど…。実は今朝、うちの犬が元気なかったんですよ。それで、ちょっと心配なんです。\n男：そうなんだ。でも倉田さん、ご両親と一緒に住んでるでしょう？ご両親が面倒を見てくれるんじゃないの？\n女：ええ、いつもはそうなんですけど、今、両親が旅行中なんです。だから、早く帰って、病院に、連れて行こうかなって思って。\n男：そうなんだ。それは心配だね。\n女：また、今度、さそってください。すみません。\n女の人は、どうして早く家に帰りたいのですか。",
