    "script": "会社で、女の人と男の人が話しています。\n女：疲れた顔してますけど、何かあったんですか。\n男：ええ、きのうは大変だったんですよ。鍵を無くしちゃったみたいで、家に入ることができなかったんです。きのうは家族も留守だったので…。それで、どうしようかと思っていたら、2階の窓が開いていることに気づいて…そこで、庭の木に登って、窓から入ろうと思ったんですよ。\n女：2階から…ですか？\n男：ええ。ところがね、それを見ていた人に泥棒と間違われて、警察を呼ばれてしまったんです。警察にはいろいろ聞かれるし、近所の人には変な目で見られるし、家族には怒られるし…。\n女：それは大変でしたねえ。\nきのうが大変な日になったのは、どうしてですか。",
