    "script": "女の人と男の人が話しています。男の人がシャツを選んだ一番の理由は何ですか。\nF：中田さん、そのシャツとても素敵ですね。\nM：ありがとう。この色、最高でしょ。買おうと決めたのはこの色なんだ。\nF：本当いいですね。\nM：たまには気分を変えようと思って、着てみたらサイズもぴったりで…\nF：その襟の形、今流行のですね。\nM：あ、そう？知らなかった。\nF：高かったんじゃないですか。\nM：いや、安かったよ。\n男の人がシャツを選んだ一番の理由は何ですか。",
