      "「あの本、来週必ずもってきてね」同樣是催促對方的語氣，但這裡應該是被催促的一方（借書的人）在回應，立場相反。",
      "正解。面對「そろそろ返してくれない？」（差不多該還我了吧）的請求，借書的一方應該道歉並說明現況，「ごめん、まだ読んでるとこで」（抱歉，還在看）最自然。"
